\label{thm:B}
Let $F$ be a GIT-semistable binary sextic over $\overline{\mathbf Q}$, that is, a nonzero sextic without roots of multiplicity $\ge4$.
\begin{enumerate}
\item $h_{\mathrm{inv}}(F)\le h_{\mathrm{GIT}}(F)+\tfrac12\log302$.
\item At every finite place the local contribution $\log\rho_v(F)-\log W_v(F)$ to $h_{\mathrm{GIT}}-h_{\mathrm{inv}}$ is nonnegative, and it vanishes if $F$ has good reduction at $v$.
\item $h_{\mathrm{GIT}}(F)\le h(gF)$ for every $g\in\operatorname{GL}_2(\overline{\mathbf Q})$. In particular, if $C:y^2=F(x,1)$ is a curve of genus two, then $h_{\mathrm{inv}}([C])\le h(gF)+\tfrac12\log302$ for every model $gF$ of $C$.
\end{enumerate}

\label{thm:C}
\begin{enumerate}
\item Every $F_R$ is GIT-semistable. The moduli map $\Phi\colon E\times E\to\mathbf P(2,4,6,10)$ is finite onto a surface, $\Phi^*\mathcal O(60)\simeq L^{\otimes120}$, and $\Phi$ factors through the finite morphism $[a:b:c]\colon E\times E\to\mathbf P^2$ of degree $18$.
\item The section $\sigma=[P_\infty^+-W]$ of the relative Jacobian has infinite order. For every $(n,m)\in\mathbf Z^2$ the fibre over $R_{n,m}=([342n]P_0,[342m]P_0)$ is smooth, $\sigma(R_{n,m})$ has positive N\'eron--Tate height, and
\[
\#\{(n,m)\in\mathbf Z^2:\ h_{\mathrm{inv}}(\Phi(R_{n,m}))\le X\}=\frac{\pi}{6\cdot342^2\,\widehat h_E(P_0)}X+O(\sqrt X).
\]
\item For each parameter $R$ listed in Proposition~\ref{prop:small}, for instance $(P_0,O)$, $(P_0,P_0)$ and $([2]P_0,O)$, the group $\operatorname{Jac}(C_R)(\mathbf Q)$ is torsion-free and contains the point $\sigma(R)$ of infinite order; in particular it has positive rank.
\end{enumerate}

\label{thm:decomposition}
Let $f\colon A\to\mathbf P(\boldsymbol w)$ be a morphism, $m$ a common multiple of the weights, $N=f^*\mathcal O_{\mathbf P(\boldsymbol w)}(m)$, $q_N=\widehat h_{N^+}$ and $\ell_N=\lambda_{N^-}$. Then
\begin{equation}\label{eq:decomp}
m\,h_{\boldsymbol w}(f(P))=q_N(P)+\ell_N(P)+O(1)
\end{equation}
uniformly on $A(\overline K)$. Consequently $m\,h_{\boldsymbol w}(f([n]P))=n^2q_N(P)+n\ell_N(P)+O(1)$ uniformly in $P$ and $n\in\mathbf Z$, and
\begin{equation}\label{eq:evenodd}
\begin{aligned}
m\bigl(h_{\boldsymbol w}(f(P))+h_{\boldsymbol w}(f(-P))\bigr)&=2q_N(P)+O(1),\\
m\bigl(h_{\boldsymbol w}(f(P))-h_{\boldsymbol w}(f(-P))\bigr)&=2\ell_N(P)+O(1).
\end{aligned}
\end{equation}

\label{thm:wnt}
In the notation of Theorem~\ref{thm:decomposition}, the limit defining $\widehat h_{f,\boldsymbol w}$ exists, does not depend on $m$, and
\begin{equation}\label{eq:wnt}
\widehat h_{f,\boldsymbol w}=\frac1m\widehat h_{N^+},\qquad h_{\boldsymbol w}\circ f=\widehat h_{f,\boldsymbol w}+\frac1m\lambda_{N^-}+O(1).
\end{equation}
It is a quadratic form, $\widehat h_{f,\boldsymbol w}([n]P)=n^2\widehat h_{f,\boldsymbol w}(P)$, and
\[
\widehat h_{f,\boldsymbol w}(P+Q)+\widehat h_{f,\boldsymbol w}(P-Q)=2\widehat h_{f,\boldsymbol w}(P)+2\widehat h_{f,\boldsymbol w}(Q).
\]
If $f$ is finite, then $\widehat h_{f,\boldsymbol w}(P)\ge0$ with equality if and only if $P$ is a torsion point.

\label{thm:count}
Let $f\colon A\to\mathbf P(\boldsymbol w)$ be finite, $\Gamma\subseteq A(K)$ a finitely generated subgroup of rank $r\ge1$ with torsion subgroup $T$, and $P_1,\ldots,P_r$ a basis of $\Gamma/T$. Let $G_\Gamma$ be the Gram matrix of $\widehat h_{f,\boldsymbol w}$ on $P_1,\ldots,P_r$ and $V_r=\pi^{r/2}/\Gamma(1+\tfrac r2)$. Then
\begin{equation}\label{eq:count}
\#\{P\in\Gamma:\ h_{\boldsymbol w}(f(P))\le X\}=\frac{|T|\,V_r}{\sqrt{\det G_\Gamma}}\,X^{r/2}+O\bigl(X^{(r-1)/2}\bigr),
\end{equation}
where for $r=1$ the error term is $O(1)$.

\label{prop:local}
Let $P=(x,y)\in E(\mathbf Q)$ be affine. At every prime $p$, $\max\{1,|x|_p^{1/2},|y|_p^{1/3}\}=\max\{1,|x|_p^{1/2}\}$, and at the real place
\[
\max\{1,|x|^{1/2}\}\le\max\{1,|x|^{1/2},|y|^{1/3}\}\le(1+|a_4|+|a_6|)^{1/6}\max\{1,|x|^{1/2}\}.
\]
Consequently
\begin{equation}\label{eq:effective}
\tfrac12h(x(P))\le h_{1,2,3}(P)\le\tfrac12h(x(P))+\tfrac16\log(1+|a_4|+|a_6|).
\end{equation}

\label{ex:two}
Let $E:y^2=x^3-2$ and $P_0=(3,5)$. Then $h_{1,2,3}(P_0)=\frac12\log3$, $[2]P_0=(\frac{129}{100},-\frac{383}{1000})$ and $h_{1,2,3}([2]P_0)=\frac12\log129$. The group $E(\mathbf Q)_{\mathrm{tors}}$ is trivial: a nonzero torsion point would be integral with $y=0$ or $y^2\mid108$ by the Nagell--Lutz theorem \cite{SilvermanAEC}, but $2$ is not a cube and none of $3,6,11,38$ is a cube. In particular $P_0$ has infinite order. The convergence in Corollary~\ref{cor:ellcanon} is visible numerically: with $t_j=4^{-j}h_{1,2,3}([2^j]P_0)$ one finds
\[
\begin{array}{c|ccccccc}
j&0&1&2&3&4&6&8\\\hline
t_j&0.5493&0.6075&0.6742&0.6742&0.6742&0.6748&0.6748
\end{array}
\]
so that $\widehat h_E(P_0)=0.6748\ldots$.

\label{thm:gitgeneral}
Let $x\in V(K)$ be semistable and $c(I)=\max_i\frac1{w_i}\log\|I_i\|_1$.
\begin{enumerate}
\item $0<\rho_v(x)\le\|x\|_v$ for every $v$, and $\rho_v(x)=\|x\|_v=1$ for all but finitely many $v$. Hence $h_{\mathrm{GIT}}(x)$ is well defined, independent of $K$, and invariant under $G(\overline{\mathbf Q})$ and under scaling.
\item $W_v(x)\le\rho_v(x)$ for every finite $v$, and $W_v(x)\le\|I\|^{*}\rho_v(x)$ for every archimedean $v$, where $\|I\|^*=\max_i\|I_i\|_1^{1/w_i}$.
\item $h_I(x)\le h_{\mathrm{GIT}}(x)+c(I)$.
\item $h_{\mathrm{GIT}}(x)\le h(gx)$ for every $g\in G(\overline{\mathbf Q})$. In particular $h_I(x)\le h(gx)+c(I)$ for every $g\in G(\overline{\mathbf Q})$.
\item If $v$ is finite and $\|x\|_v=1$, then $0\le\log\rho_v(x)-\log W_v(x)\le-\log W_v(x)$. The local difference vanishes whenever some $I_i(x)$ is a $v$-adic unit.
\end{enumerate}

\label{prop:pencil}
The Igusa--Clebsch invariants of $F_{T,U}$ are
\begin{align*}
I_2&=10\,Q_2,\qquad I_{10}=144\,D_5^2,\\
I_4&=4\,(13T^4-78T^3U+183T^2U^2-198TU^3+108U^4),\\
I_6&=120\,(5T^6-45T^5U+184T^4U^2-429T^3U^3\\
&\qquad+599T^2U^4-474TU^5+180U^6).
\end{align*}
The forms $Q_2$ and $D_5$ have no common zero over $\overline{\mathbf Q}$, and none over $\overline\mathbf F_p$ for $p\notin\{2,3,5,7\}$. The curve $C_t$ is smooth exactly when $D_5(T,U)\ne0$.

\label{thm:local}
For every primitive $(T,U)\in\mathbf Z^2$,
\begin{equation}\label{eq:exactlocal}
H_*(T,U)=H(T,U)+\epsilon_\infty(T,U)+\sum_{p\in\{2,3,5,7\}}\epsilon_p(T,U),
\end{equation}
with
\begin{gather*}
-\log2\le\epsilon_2\le0,\qquad-\tfrac12\log p\le\epsilon_p\le0\quad(p=3,5,7),\\
\tfrac12\log\tfrac85\le\epsilon_\infty\le\tfrac12\log31.
\end{gather*}
The bounds are sharp: $\epsilon_2=-\log2$ whenever $2^5\mid U$, $\epsilon_\infty=\frac12\log\frac85$ at $(T,U)=(5,2)$, and $\epsilon_\infty=\frac12\log31$ at $(T,U)=(1,-1)$.

\label{thm:quadratic}
Every member of \eqref{eq:quadfamily} with $(a:b:c)\in\mathbf P^2(\overline{\mathbf Q})$ is semistable, and $F^{(2)}_{1,0,0}=Z^6f_0(X/Z)$ is squarefree. The moduli map $\Phi_2=\psi_2\circ\phi\colon A\to\mathcal X$ is finite onto a surface, $\psi_2^*\mathcal H\simeq\mathcal O_{\mathbf P^2}(120)$, $\Phi_2^*\mathcal H\simeq L^{\otimes120}$, and
\begin{equation}\label{eq:quad-height}
h_{\mathrm{inv}}(\Phi_2(R))=6\widehat h_E(p_1R)+6\widehat h_E(p_2R)+O(1).
\end{equation}
Over the open set where $a\operatorname{Disc}(F^{(2)})\ne0$, the class $\sigma=[P_\infty^+-W]$ is a section of the relative Jacobian.

\label{lem:criteria}
Let $J/\mathbf Q$ be an abelian variety and let $p,q\ge3$ be primes of good reduction.
\begin{enumerate}
\item If $\ell$ is a prime with $\ell\nmid\#J(\mathbf F_q)$ and $D\in J(\mathbf Q)$ is such that $\ell$ divides the order of the reduction of $D$ in $J(\mathbf F_p)$, then $D$ has infinite order.
\item If $p_1,\ldots,p_k\ge3$ are primes of good reduction with $\gcd_i\#J(\mathbf F_{p_i})=1$, then $J(\mathbf Q)_{\mathrm{tors}}=0$.
\end{enumerate}

\label{thm:grid}
Let $M=342$ and $R_{n,m}=([Mn]P_0,[Mm]P_0)$ for $(n,m)\in\mathbf Z^2$. For every $(n,m)$ the curve $C_{n,m}:y^2=F^{(2)}_{R_{n,m}}(x,1)$ is smooth, the class $\sigma(R_{n,m})$ has infinite order, so that $\operatorname{Jac}(C_{n,m})(\mathbf Q)$ has positive rank, and the local GIT corrections of $F^{(2)}_{R_{n,m}}$ at $13$ and $17$ vanish. Moreover
\begin{equation}\label{eq:grid-asymptotic}
\#\{(n,m)\in\mathbf Z^2:\ h_{\mathrm{inv}}(\Phi_2(R_{n,m}))\le X\}=\frac{\pi}{6M^2\widehat h_E(P_0)}X+O(\sqrt X),
\end{equation}
and the number of distinct moduli points among these curves with $h_{\mathrm{inv}}\le X$ is $\gg X$.

The roots of $f_0$ are distinct modulo $31$, and $\#C_0(\mathbf F_{31})=36$, $\#C_0(\mathbf F_{31^2})=942$. Hence the characteristic polynomial of Frobenius is
\begin{equation}\label{eq:frob31}
P_{31}(T)=T^4+4T^3-2T^2+124T+31^2,
\end{equation}
and $\#J_0(\mathbf F_{31})=P_{31}(1)=1088$. The reduction is ordinary because $31\nmid-2$, and $P_{31}$ is irreducible over $\mathbf Q$. Moreover
\begin{multline*}
\operatorname{Res}_X\bigl(P_{31}(X),P_{31}(TX)\bigr)=31^4(T-1)^4(31T^4+64T^3+82T^2+64T+31)^2\\
\cdot(961T^4-620T^3+934T^2-620T+961),
\end{multline*}
and both quartic factors are irreducible with leading coefficients $31$ and $961$, so they have no roots of unity as zeros. Hence no quotient of two distinct Frobenius eigenvalues is a root of unity. Consequently, for every $r\ge1$ the $r$-th powers of the eigenvalues are four distinct conjugates, and the characteristic polynomial of the $r$-th power of Frobenius is irreducible over $\mathbf Q$. The reduction of $J_0$ is therefore simple over every finite extension of $\mathbf F_{31}$, since an isogeny decomposition over $\mathbf F_{31^r}$ would factor this polynomial; compare \cite{HoweZhu}. An abelian subvariety of $J_{0,\overline{\mathbf Q}}$ would be defined over a number field and would have good reduction at the primes above $31$, giving a proper abelian subvariety of the reduction. Hence $J_0$ is absolutely simple.

\label{thm:general}
In the setting above, let $s_\beta=\delta_\beta/(2d_\beta)$. There is a degree-zero class $\nu_\beta\in\operatorname{Pic}^0(B_{\overline{\mathbf Q}})\otimes\mathbf Q$ such that for all $b\in B^\circ(\overline{\mathbf Q})$
\begin{equation}\label{eq:general}
\begin{aligned}
\widehat h_{\mathscr J_{\beta,b}}(\sigma_\beta(b))&=s_\beta\,h_{\mathrm{inv}}(\psi_2(\beta(b)))+h_{\nu_\beta}(b)+O_\beta(1)\\
&=s_\beta\,h_{\mathrm{inv}}(\psi_2(\beta(b)))+O_\beta\Bigl(\sqrt{h_{\mathrm{inv}}(\psi_2(\beta(b)))+1}\Bigr).
\end{aligned}
\end{equation}
If $B$ has genus zero, then $\nu_\beta=0$ and the error is $O_\beta(1)$. For every $n\ge1$ the set of $b\in B^\circ(\overline{\mathbf Q})$ with $[k(b):k]\le n$ and $\sigma_\beta(b)$ torsion is finite.

\label{thm:ray}
For every $(u,v)\ne(0,0)$ there are $\delta_{u,v}>0$ and a unique $R_{u,v}\in E(\mathbf Q)\otimes\mathbf Q$ such that, uniformly for $T\in U_{u,v}(\overline{\mathbf Q})$,
\begin{align}
\widehat h_J(\sigma_{u,v}(T))&=\delta_{u,v}\widehat h_E(T)+2\langle T,R_{u,v}\rangle_E+O_{u,v}(1),\label{eq:ray-nt}\\
h_{\mathrm{inv}}(\Phi_2(\alpha_{u,v}(T)))&=6(u^2+v^2)\widehat h_E(T)+O_{u,v}(1),\label{eq:ray-git}
\end{align}
and
\begin{multline}\label{eq:ray-ratio}
\widehat h_J(\sigma_{u,v}(T))=\frac{\delta_{u,v}}{6(u^2+v^2)}\,h_{\mathrm{inv}}(\Phi_2(\alpha_{u,v}(T)))\\
+O_{u,v}\Bigl(\sqrt{h_{\mathrm{inv}}(\Phi_2(\alpha_{u,v}(T)))+1}\Bigr).
\end{multline}
Moreover $(\Phi_2\circ\alpha_{u,v})^*\mathcal H\simeq\mathcal O_E(360(u^2+v^2)O)$.

\label{cor:ray-asymptotic}
Let $M=342$, $T_n=[Mn]P_0$, $\eta(n)=\widehat h_J(\sigma_{u,v}(T_n))$ and $\mu(n)=h_{\mathrm{inv}}(\Phi_2(\alpha_{u,v}(T_n)))$. Every fibre is smooth and $\eta(n)>0$ for all $n\in\mathbf Z$. With $\kappa_{u,v}=2M\langle P_0,R_{u,v}\rangle_E$,
\begin{align*}
\eta(n)&=\delta_{u,v}M^2\widehat h_E(P_0)n^2+\kappa_{u,v}n+O(1),\\
\mu(n)&=6(u^2+v^2)M^2\widehat h_E(P_0)n^2+O(1),
\end{align*}
so that $\frac12(\eta(n)+\eta(-n))=s(u:v)\cdot\frac12(\mu(n)+\mu(-n))+O(1)$ and
\[
\#\{n\in\mathbf Z:\ \eta(n)\le X\}=\frac{2}{M\sqrt{\delta_{u,v}\widehat h_E(P_0)}}\sqrt X+O(1).
\]
